"""Build the concise current report; retain detailed experiment history separately."""
from pathlib import Path
import json
import nbformat as nbf
from nbclient import NotebookClient

OUT=Path(__file__).resolve().parents[1]

def build():
    md=nbf.v4.new_markdown_cell;code=nbf.v4.new_code_cell;nb=nbf.v4.new_notebook()
    nb.cells=[
        md('# Dance stage mapping\n\nThe aim is to locate each dancer on the floor before detecting formations. The overnight tests support **YOLO boxes → identity tracking → learned floor-support point and visibility → perspective transform → offline smoothing**. The points improved, but crowded groups still cause missing dancers and confused identities. This is the best tested candidate, not a finished twenty-person tracker.'),
        code("from pathlib import Path\nimport json\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom IPython.display import display, Image, Video\nroot = Path.cwd()\nassert (root / 'final_confirmation/results.json').exists(), 'Open from Dance_Overnight.'\nread = lambda p: json.loads((root / p).read_text())\nselection = read('final_confirmation/frozen_selection.json')\nresults = read('final_confirmation/results.json')"),
        md('## 1. Watch what changed\n\nThe left side uses box bottoms; the right predicts actual floor support. Boxes, IDs, visibility decisions and smoothing are otherwise identical. This clearer twelve-second clip includes training images, so use it to understand the behaviour, not to measure accuracy.'),
        code("display(Video('videos/latest_development_demo.mp4', embed=False, width=1100))"),
        md('## 2. Define a useful label\n\nFor each distinguishable dancer, label a person box and a contact status. When the primary floor supports are visible, add one point at their centre: planted feet, grounded knees, mixed knee/foot support, seated contact or hands-only support. If a primary support is hidden, airborne or too ambiguous, do not invent a coordinate.\n\nA silhouette or an ankle is not necessarily a floor contact. That is why this experiment trains a separate support estimator rather than relying on segmentation alone. Uncertain examples are excluded from clean supervision.'),
        code("display(Image(filename=str(root / 'figures/label_examples.jpg'), width=1050))"),
        md('## 3. Train on varied poses\n\nThe selected support network uses an ImageNet-pretrained ResNet18 backbone, a point heatmap and a visible-contact score. Training balances postures and varies crop position, scale, brightness and horizontal orientation. The detector was fine-tuned separately on 30 unique training images. A support-crop collection is not automatically a complete detector dataset: all distinguishable dancers need boxes for detector training.'),
        code("manifest = read('data/development_ending.json')\ncounts = []\nfor split in ['train', 'val']:\n    rows = [o for d in manifest.values() for k in d[split] for o in d['labels'][str(k)] if o['box'] is not None and o['contact'] != 'uncertain']\n    counts.append({'Split': split, 'Frames': sum(len(d[split]) for d in manifest.values()), 'Usable dancer crops': len(rows), 'Visible contacts': sum(o['floor'] is not None for o in rows)})\ndisplay(pd.DataFrame(counts))\nprint('Selected support run:', selection['support']['run'], '| epoch:', selection['support']['epoch'])"),
        code("history = read('runs/' + selection['support']['run'] + '/history.json')\nfig, axes = plt.subplots(1, 2, figsize=(11, 3.3))\nepochs = [r['epoch'] for r in history]\naxes[0].plot(epochs, [r['train_loss'] for r in history], label='Training')\naxes[0].plot(epochs, [r['validation']['loss'] for r in history], label='Validation')\naxes[0].set(xlabel='Epoch', ylabel='Combined loss', title='Support training'); axes[0].legend()\njoint = [next(x['joint_f1'] for x in r['validation']['threshold_options'] if x['threshold'] == selection['threshold']) for r in history]\naxes[1].plot(epochs, joint, color='#16745e')\naxes[1].axvline(selection['support']['epoch'], color='#b18a43', linestyle='--', label='Selected checkpoint')\naxes[1].set(xlabel='Epoch', ylabel='Joint F1', title='Visible and correctly placed at 3%'); axes[1].legend()\nfig.tight_layout(); plt.show()"),
        md('## 4. Test away from the training frames\n\nModels and thresholds were selected on development data. The newest detector, support model and filter were frozen before seven new evaluation images were labeled. This block contains 103 distinguishable bodies: 46 visible contacts, 50 hidden and 7 uncertain. None entered training.\n\nA correct position is within the stated percentage of mat width. Missing predictions count as misses. This is a small, correlated sample from the same video, with approximate assistant reference labels; it does not establish generalisation to other choreographies. Identity switches are not scored in this block.'),
        code("rows = []\nfor name, result in results['candidates'].items():\n    a = result['all']; n = a['visible_references']\n    rows.append({'Pipeline': name, 'Within 1%': f\"{a['correct_by_tolerance_pct_width']['1']}/{n}\", 'Within 3%': f\"{a['correct_by_tolerance_pct_width']['3']}/{n}\", 'Available': f\"{a['available_visible']}/{n}\", 'Hidden reported visible': f\"{a['hidden_measured']}/{a['hidden_references']}\"})\ndisplay(pd.DataFrame(rows))\ndisplay(Video('videos/final_confirmation_point_ablation.mp4', embed=False, width=1100))"),
        md('The selected pipeline placed **29/46** visible contacts within 3%, versus **19/46** for box bottoms in the same pipeline and **25/46** for the established pipeline. It still produced no usable position for 12/46 visible references. On a previously inspected crowd block, the expanded detector/support combination scored 49/77 versus 51/77 before. The improvement is not uniform.\n\nEarlier frozen comparisons remain in `reserved_evaluation/results.json` and `backup_evaluation/results.json`. They tested earlier pipeline versions; do not combine their scores into one headline accuracy.'),
        md('## 5. Reduce jitter without hiding uncertainty\n\nThe retained filter fits the recorded trajectory, downweights outliers and fills short gaps. Solid dots are model outputs, hollow dots are estimates, and unknown points are omitted. It uses future frames and can spread a sudden movement slightly before and after it happens. It is not a zero-delay live tracker.\n\nA separate crop-sensitivity check moved each development box by ±4 pixels while keeping the image fixed. For 112 visible reference contacts, the learned point moved a median **0.36 pixels**, versus **4 pixels** for box bottoms, without smoothing. This tests small box jitter, not identity swaps.\n\nThe mat transform stays fixed. A background audit found at most 1.66 pixels of anchor drift, with no meaningful ending zoom. The width/depth ratio is assumed to be 1.6; errors are relative, not measured in metres.'),
        md('## 6. What the other trials taught us\n\nAcross 32 support-training runs, five detector fine-tunes and tracking/filtering comparisons:\n\n- More seated/dim-light examples improved that posture, but did not solve overlapping bodies.\n- Larger detector inputs, synthetic occlusion, crop extension and learned re-identification did not establish a reliable overall gain.\n- Temporal models using neighbouring frames reached 72/77 correct development positions at 3%, versus 74/77 for the retained single-image preset.\n- Long-gap interpolation added estimates without demonstrating accuracy gains.\n- Two crop views gave 73/77 versus 74/77 with ten views, at 16.0 versus 3.6 support-head frames/s. These timings exclude detection, tracking and rendering. The reported accuracy preset keeps ten views.\n\nThe detailed trials and historical results are in `Experiment_History.ipynb` and the report. No rejected option silently replaces the frozen candidate.'),
        md('## 7. Give the team a small review task\n\nUse the three disjoint CVAT packs in `CVAT_Review/GUIDE.html`. Each teammate reviews **20 training images plus 3–4 validation images**. Keep the split tags. Check missing/duplicate boxes, the supporting limbs and the visible/hidden/airborne/uncertain status.\n\nA repeat review agreed on status in 17/20 crops. For 14 contacts marked visible both times, points differed by a median 6.3 source pixels. This same-assistant check is not human agreement; it shows why the prepared labels need review before scaling up. The guide flags the ambiguous examples.\n\nReview these labels first. Then retrain and test again. For persistent identities, the next distinct annotation task is short tracks through overlap events. Formation shapes and dancer-to-shape errors should wait until positions and identities are trustworthy.'),
        md('## 8. Reproduce the result\n\n`REPRODUCE.txt` gives the commands, selected weights and manifests. The newest cached replay reproduces the reported map scores. Fresh detector/support inference matched the saved outputs on ten sampled frames, including when run from the portable copy. That verifies inference and packaging; it does not promise identical weights after retraining.\n\nThe 97-second stress test is `videos/late_full_section.mp4`. It includes training frames and still loses dancers in crowded seated groups. The portable folder includes the source clips, notebook, code, weights and CVAT review exports.\n\nSources: [Ultralytics tracking](https://docs.ultralytics.com/modes/track/), [pose labels](https://docs.ultralytics.com/datasets/pose/), [ByteTrack](https://arxiv.org/abs/2110.06864), [BoT-SORT](https://arxiv.org/abs/2206.14651), [OSNet](https://arxiv.org/abs/1905.00953).')
    ]
    completed=sum((p/'complete.json').exists() for p in (OUT/'runs').iterdir() if p.is_dir())
    for cell in nb.cells:
        if cell.cell_type=='markdown':cell.source=cell.source.replace('Across 32 support-training runs',f'Across {completed} support-training runs')
        if cell.cell_type=='markdown' and cell.source.startswith('## 1.'):
            cell.source=cell.source.replace('This clearer twelve-second clip includes training images, so use it to understand the behaviour, not to measure accuracy.','This twelve-second excerpt (3:05–3:17 in the source) was selected for high model-output coverage and includes training images. Use it to understand the behaviour, not to measure accuracy.')
        if cell.cell_type=='code':cell.source=cell.source.replace('videos/latest_development_demo.mp4','videos/clearer_showcase.mp4')
        if cell.cell_type=='markdown' and cell.source.startswith('## 5.'):
            cell.source+='\n\nAn optional follow-up adds bounded hollow estimates. On the already inspected difficult block it increased correct visible positions from 29 to 31/46, while estimates for hidden contacts increased from 2 to 8/50. Those hidden positions cannot be verified. This exploratory option stays separate from the frozen result; see `videos/optional_estimates_crowd.mp4`.'
        if cell.cell_type=='markdown' and cell.source.startswith('## 6.') and (OUT/'seed_repeatability/results.json').exists():
            seeds=json.loads((OUT/'seed_repeatability/results.json').read_text())['models'];scores={k:v['controlled']['correct_by_tolerance_pct_width']['3'] for k,v in seeds.items()}
            cell.source+=f"\n\nTwo repeat training seeds gave {scores['v9_repeat_wide_s29']}/77 and {scores['v9_repeat_wide_s43']}/77 correct controlled-development positions at 3%, versus {scores['v6_attention_wide_s17']}/77 for the original seed. Averaging all three gave {scores['ensemble']}/77, at roughly three times the support inference work. This is a fixed-threshold development audit, not a new independent test."
    nb.metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'}}
    NotebookClient(nb,timeout=120,kernel_name='python3',resources={'metadata':{'path':str(OUT)}}).execute()
    nbf.write(nb,OUT/'Dance_Research_Notebook.ipynb')
    print('Concise current notebook executed',flush=True)

if __name__=='__main__':build()
